// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class ServiceVariableMetadataTest {

	@Test
	void filterCanBeSplicedBeforeItsArgumentIsAttached() {
		StatementPattern body = pattern("subject");
		Service service = service(body);
		Filter gate = new Filter();
		gate.setCondition(Var.of("condition"));

		body.replaceWith(gate);
		gate.setArg(body);

		assertSame(gate, service.getArg());
		assertEquals(Set.of("subject", "predicate", "object", "condition"), service.getServiceVars());

		gate.replaceWith(body);

		assertSame(body, service.getArg());
		assertEquals(Set.of("subject", "predicate", "object"), service.getServiceVars());
	}

	@Test
	void replacementCanContainAnIncompleteDescendant() {
		Service service = service(pattern("oldSubject"));
		Filter nested = new Filter();

		service.setArg(new Join(pattern("leftSubject"), nested));
		nested.setCondition(Var.of("condition"));
		nested.setArg(pattern("rightSubject"));

		assertEquals(Set.of("leftSubject", "rightSubject", "predicate", "object", "condition"),
				service.getServiceVars());
	}

	@Test
	void completedReplacementRefreshesVariablesAndInvalidatesOwnership() {
		Service service = service(pattern("oldSubject"));
		service.setBNodeReferenceMetadata(Set.of("fixed"), Set.of("reference"), true);

		service.setArg(pattern("newSubject"));

		assertEquals(Set.of("newSubject", "predicate", "object"), service.getServiceVars());
		assertFalse(service.isBNodeReferenceMetadataInitialized());
		assertFalse(service.hasBNodeReferences());
		assertFalse(service.containsBNodeReferenceSyntax());
	}

	@Test
	void cloningAfterReplacementPreservesIndependentVariables() {
		Service service = service(pattern("oldSubject"));
		service.setArg(pattern("newSubject"));

		Service clone = service.clone();

		assertNotSame(service.getArg(), clone.getArg());
		assertNotSame(service.getServiceVars(), clone.getServiceVars());
		assertEquals(Set.of("newSubject", "predicate", "object"), clone.getServiceVars());

		clone.setArg(pattern("cloneSubject"));

		assertEquals(Set.of("newSubject", "predicate", "object"), service.getServiceVars());
		assertEquals(Set.of("cloneSubject", "predicate", "object"), clone.getServiceVars());
	}

	@Test
	void extractedBodyFactoryPreservesNestedServiceWhileLegacyWrappersAndCachesRemainSupported() {
		var values = SimpleValueFactory.getInstance();
		String nestedBody = "SERVICE <urn:inner> {?subject ?predicate ?object}";
		Service nested = new Service(Var.of("inner", values.createIRI("urn:inner")), pattern("subject"), nestedBody,
				Map.of(), null, false);
		Service invocation = Service.fromBody(Var.of("outer", values.createIRI("urn:outer")), nested, nestedBody,
				Map.of(), null, false);
		String ask = invocation.getAskQueryString();
		String select = invocation.getSelectQueryString(Set.of("subject"));
		assertEquals(nestedBody, invocation.getServiceExpressionString());
		assertTrue(ask.contains(nestedBody));
		assertTrue(select.contains(nestedBody));

		Service legacy = new Service(Var.of("outer", values.createIRI("urn:outer")), nested.clone(),
				"SERVICE <urn:outer> {" + nestedBody + "}", Map.of(), null, false);
		assertEquals(nestedBody, legacy.getServiceExpressionString());
		Service clone = invocation.clone();
		assertEquals(ask, clone.getAskQueryString());
		assertEquals(select, clone.getSelectQueryString(Set.of("subject")));
		clone.setArg(pattern("replacement"));
		clone.setExpressionString("SERVICE <urn:outer> {?replacement ?predicate ?object}");
		assertEquals("?replacement ?predicate ?object", clone.getServiceExpressionString());
		assertNotEquals(ask, clone.getAskQueryString());
		assertNotEquals(select, clone.getSelectQueryString(Set.of("subject")));
		assertEquals(ask, invocation.getAskQueryString());
		assertEquals(nestedBody, invocation.getServiceExpressionString());
	}

	private static StatementPattern pattern(String subject) {
		return new StatementPattern(Var.of(subject), Var.of("predicate"), Var.of("object"));
	}

	private static Service service(TupleExpr body) {
		return new Service(Var.of("endpoint"), body, "", Map.of(), null, false);
	}
}
